<?php
namespace Delnavazan\Platform\Portals;

final class PortalCapabilityService {
    private function table(string $n):string { global $wpdb; return $wpdb->prefix.'dzn_'.$n; }
    private function digest(string $v):string { return hash_hmac('sha256',$v,wp_salt('dzn_portal_capability_public')); }
    private function uid():string { return substr(str_replace('-','',wp_generate_uuid4()),0,26); }
    private function enabled():void { if((string)get_option(PortalRule::PUBLIC_ACTION_OPTION,'')!==PortalRule::PUBLIC_ACTION_ENABLED_VALUE)throw new \InvalidArgumentException('portal_route_disabled'); }
    private function owner(int $l,int $s,string $p,?int $student):array { return PortalOwnerPorts::capability()->binding($l,$s,$p,$student); }
    private function bind(array $o,string $p,int $g,string $e):string { return PortalRule::CAPABILITY_BINDING_VERSION.'|'.$p.'|'.$o['lesson_uid'].'|'.$o['schedule_version_uid'].'|'.$g.'|'.$e; }
    private function seal(string $v):array { $k=hash('sha256',wp_salt('secure_auth').'dzn_portal_join_target',true);$n=random_bytes(12);$t='';$c=openssl_encrypt($v,'aes-256-gcm',$k,OPENSSL_RAW_DATA,$n,$t);if($c===false)throw new \RuntimeException('portal_join_target_unavailable');return array(base64_encode($c.$t),base64_encode($n)); }
    private function unseal(string $c,string $n):string { $k=hash('sha256',wp_salt('secure_auth').'dzn_portal_join_target',true);$r=base64_decode($c,true);$i=base64_decode($n,true);if($r===false||$i===false||strlen($r)<16)throw new \RuntimeException('portal_join_target_unavailable');$v=openssl_decrypt(substr($r,0,-16),'aes-256-gcm',$k,OPENSSL_RAW_DATA,$i,substr($r,-16));if(!is_string($v))throw new \RuntimeException('portal_join_target_unavailable');return$v; }
    private function event(int $lesson,int $cap,string $purpose,int $generation,string $type,string $reason):void { PortalRule::reason($reason);global $wpdb;$seq=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(event_sequence),0)+1 FROM {$this->table('portal_public_capability_events')} WHERE lesson_id=%d FOR UPDATE",$lesson));$now=gmdate('Y-m-d H:i:s');if(false===$wpdb->insert($this->table('portal_public_capability_events'),array('uid'=>$this->uid(),'lesson_id'=>$lesson,'capability_id'=>$cap,'event_sequence'=>$seq,'event_type'=>$type,'purpose'=>$purpose,'generation'=>$generation,'reason_code'=>$reason,'evidence_channel'=>'admin','evidence_reference_digest'=>hash('sha256',$type.'|'.$cap.'|'.$seq),'recorded_at'=>$now,'created_at'=>$now,'created_by'=>get_current_user_id())))throw new \RuntimeException('portal_capability_persistence_failed'); }
    private function command(int $lesson,string $purpose,string $operation,string $reason,?int $id,string $state,string $commandKey,string $payload):void { PortalRule::reason($reason);global $wpdb;$now=gmdate('Y-m-d H:i:s');if(false===$wpdb->insert($this->table('portal_public_capability_commands'),array('uid'=>$this->uid(),'command_domain'=>'portal_capability','operation'=>$operation,'command_key_digest'=>$this->digest($commandKey),'command_payload_digest'=>hash('sha256',$payload),'lesson_id'=>$lesson,'purpose'=>$purpose,'reason_code'=>$reason,'result_capability_id'=>$id,'result_state'=>$state,'created_at'=>$now,'created_by'=>get_current_user_id())))throw new \RuntimeException('portal_capability_persistence_failed'); }
    private function replayCommand(string $key,string $payload,int $lesson,string $purpose):?array { global $wpdb;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('portal_public_capability_commands')} WHERE command_key_digest=%s FOR UPDATE",$this->digest($key)));if(!$row)return null;if(!hash_equals((string)$row->command_payload_digest,hash('sha256',$payload)))throw new \InvalidArgumentException('command_replay_conflict');$cap=$row->result_capability_id?(int)$row->result_capability_id:0;return array('capability_id'=>$cap,'state'=>(string)$row->result_state,'replayed'=>true); }
    public function mint(int $lessonId,int $scheduleVersionId,string $purpose,int $expiresAt,string $joinTarget='',?int $studentId=null,bool $transaction=true,?string $commandKey=null):array {
        if(!current_user_can('dzn_manage_portal_capabilities'))throw new \RuntimeException('Unauthorized');if(!in_array($purpose,array(PortalRule::JOIN,PortalRule::ABSENCE),true))throw new \InvalidArgumentException('portal_vocabulary_member_not_allowed');if($expiresAt<=time())throw new \InvalidArgumentException('portal_capability_expiry_missing');if($expiresAt>time()+PortalRule::MAX_CAPABILITY_TTL_SECONDS)throw new \InvalidArgumentException('portal_capability_ttl_not_allowed');$parts=parse_url($joinTarget);$host=strtolower((string)($parts['host']??''));if($purpose===PortalRule::JOIN&&(!$parts||($parts['scheme']??'')!=='https'||!in_array($host,PortalRule::SAFE_JOIN_HOSTS,true)))throw new \InvalidArgumentException($joinTarget===''?'portal_join_target_not_declared':'portal_join_target_not_allowlisted');if($purpose===PortalRule::ABSENCE)$joinTarget='https://meet.google.com/';[$cipher,$nonce]=$this->seal($joinTarget);$commandKey=trim((string)($commandKey??''));if($commandKey==='')$commandKey=wp_generate_uuid4();$payload=wp_json_encode(array($lessonId,$scheduleVersionId,$purpose,$expiresAt,$joinTarget,$studentId));global $wpdb;$root=$this->table('portal_lesson_capability_roots');$cap=$this->table('portal_public_capabilities');$now=gmdate('Y-m-d H:i:s');if($transaction)$wpdb->query('START TRANSACTION');try{$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$root}(lesson_id,created_at,created_by) VALUES(%d,%s,%d)",$lessonId,$now,get_current_user_id()));$wpdb->get_row($wpdb->prepare("SELECT id FROM {$root} WHERE lesson_id=%d FOR UPDATE",$lessonId));if($replay=$this->replayCommand($commandKey,$payload,$lessonId,$purpose)){if($transaction)$wpdb->query('COMMIT');return$replay;}$owner=$this->owner($lessonId,$scheduleVersionId,$purpose,$studentId);if($purpose===PortalRule::ABSENCE)$studentId=(int)$owner['student_id'];$generation=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(generation),0)+1 FROM {$cap} WHERE lesson_id=%d AND purpose=%s FOR UPDATE",$lessonId,$purpose));$handle=bin2hex(random_bytes(PortalRule::HANDLE_ENTROPY_BYTES));$expires=gmdate('Y-m-d H:i:s',$expiresAt);$token=hash_hmac('sha256',$this->bind($owner,$purpose,$generation,$expires),wp_salt('dzn_portal_capability_public'));$data=array('uid'=>$this->uid(),'lesson_id'=>$lessonId,'schedule_version_id'=>$scheduleVersionId,'subject_student_id'=>$studentId,'purpose'=>$purpose,'generation'=>$generation,'handle_digest'=>$this->digest($handle),'token_digest'=>$this->digest($handle.$token),'join_target_ciphertext'=>$cipher,'join_target_nonce'=>$nonce,'join_target_key_version'=>'dzn_portal_join_target','join_target_cipher_version'=>'aes-256-gcm-v1','join_target_host'=>$host,'state'=>'active','active_slot'=>1,'issued_at'=>$now,'expires_at'=>$expires,'reason_code'=>'phase_w_declared_default','created_at'=>$now,'created_by'=>get_current_user_id());if(false===$wpdb->insert($cap,$data))throw new \RuntimeException('portal_capability_persistence_failed');$id=(int)$wpdb->insert_id;$this->event($lessonId,$id,$purpose,$generation,'minted','phase_w_declared_default');$this->command($lessonId,$purpose,'mint','phase_w_declared_default',$id,'active',$commandKey,$payload);if($transaction)$wpdb->query('COMMIT');return array('capability_id'=>$id,'handle'=>$handle,'token'=>$handle.$token,'url'=>home_url('/wp-json/delnavazan-platform/v1/portal/join?handle='.rawurlencode($handle).'&token='.rawurlencode($handle.$token)));}catch(\Throwable $e){if($transaction)$wpdb->query('ROLLBACK');throw$e;}}
    private function check(object $row,string $token,?string $purpose):object { if(!hash_equals((string)$row->token_digest,$this->digest($token)))throw new \InvalidArgumentException('portal_capability_signature_invalid');if(strlen($token)<64)throw new \InvalidArgumentException('portal_capability_signature_invalid');$owner=$this->owner((int)$row->lesson_id,(int)$row->schedule_version_id,(string)$row->purpose,$row->subject_student_id===null?null:(int)$row->subject_student_id);$expected=hash_hmac('sha256',$this->bind($owner,$row->purpose,(int)$row->generation,$row->expires_at),wp_salt('dzn_portal_capability_public'));if(!hash_equals(substr($token,-64),$expected))throw new \InvalidArgumentException('portal_capability_signature_invalid');if($purpose!==null&&$row->purpose!==$purpose)throw new \InvalidArgumentException('portal_capability_purpose_mismatch');if((string)$row->state==='consumed')throw new \InvalidArgumentException('portal_capability_consumed');if((string)$row->state!=='active')throw new \InvalidArgumentException($row->state==='revoked'?'portal_capability_revoked':'portal_capability_superseded');if(strtotime($row->expires_at)<=time())throw new \InvalidArgumentException('portal_capability_expired');return$row; }
    public function verify(string $handle,string $token,?string $purpose=null):object { $this->enabled();if(!preg_match('/^[a-f0-9]{64}$/',$handle)||strlen($token)<64)throw new \InvalidArgumentException('portal_capability_handle_malformed');global $wpdb;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('portal_public_capabilities')} WHERE handle_digest=%s LIMIT 1",$this->digest($handle)));if(!$row)throw new \InvalidArgumentException('portal_capability_unknown');return$this->check($row,$token,$purpose); }
    public function join(string $handle,string $token):string { $this->enabled();if(!preg_match('/^[a-f0-9]{64}$/',$handle)||strlen($token)<64)throw new \InvalidArgumentException('portal_capability_handle_malformed');global $wpdb;$wpdb->query('START TRANSACTION');try{$hint=$wpdb->get_row($wpdb->prepare("SELECT id,lesson_id FROM {$this->table('portal_public_capabilities')} WHERE handle_digest=%s LIMIT 1",$this->digest($handle)));if(!$hint)throw new \InvalidArgumentException('portal_capability_unknown');$wpdb->get_row($wpdb->prepare("SELECT id FROM {$this->table('portal_lesson_capability_roots')} WHERE lesson_id=%d FOR UPDATE",$hint->lesson_id));$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('portal_public_capabilities')} WHERE id=%d FOR UPDATE",$hint->id));if(!$row)throw new \InvalidArgumentException('portal_capability_unknown');$row=$this->check($row,$token,PortalRule::JOIN);$url=$this->unseal($row->join_target_ciphertext,$row->join_target_nonce);$seq=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(action_sequence),0)+1 FROM {$this->table('portal_public_action_events')} WHERE capability_id=%d FOR UPDATE",$row->id));$now=gmdate('Y-m-d H:i:s');if(false===$wpdb->insert($this->table('portal_public_action_events'),array('uid'=>$this->uid(),'capability_id'=>$row->id,'lesson_id'=>$row->lesson_id,'purpose'=>$row->purpose,'action_sequence'=>$seq,'action_state'=>'redirected','redemption_key_digest'=>$this->digest($handle.'|join|'.$seq),'request_fingerprint_digest'=>hash('sha256',wp_json_encode($_REQUEST)),'occurred_at'=>$now,'created_at'=>$now)))throw new \RuntimeException('portal_action_evidence_persistence_failed');$wpdb->query('COMMIT');return$url;}catch(\Throwable$e){$wpdb->query('ROLLBACK');throw$e;} }
    public function revoke(int $capabilityId,string $reason,?string $commandKey=null):void { $this->transition($capabilityId,$reason,'revoked',$commandKey); }
    public function rotate(int $lessonId,int $scheduleVersionId,string $purpose,int $expiresAt,string $joinTarget,string $reason,?string $commandKey=null):array { if(!current_user_can('dzn_manage_portal_capabilities'))throw new \RuntimeException('Unauthorized');PortalRule::operatorReason($reason);$commandKey=trim((string)($commandKey??''));if($commandKey==='')$commandKey=wp_generate_uuid4();$payload=wp_json_encode(array($lessonId,$scheduleVersionId,$purpose,$expiresAt,$joinTarget,$reason));global $wpdb;$wpdb->query('START TRANSACTION');try{$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$this->table('portal_lesson_capability_roots')}(lesson_id,created_at,created_by) VALUES(%d,%s,%d)",$lessonId,gmdate('Y-m-d H:i:s'),get_current_user_id()));$wpdb->get_row($wpdb->prepare("SELECT id FROM {$this->table('portal_lesson_capability_roots')} WHERE lesson_id=%d FOR UPDATE",$lessonId));if($replay=$this->replayCommand($commandKey,$payload,$lessonId,$purpose)){$wpdb->query('COMMIT');return$replay;}$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('portal_public_capabilities')} WHERE lesson_id=%d AND purpose=%s AND state='active' AND active_slot=1 FOR UPDATE",$lessonId,$purpose));if(!$old)throw new \InvalidArgumentException('portal_capability_generation_conflict');$changed=$wpdb->query($wpdb->prepare("UPDATE {$this->table('portal_public_capabilities')} SET state='superseded',active_slot=NULL,revoked_at=%s,revoked_by=%d,revocation_reason_code=%s WHERE id=%d AND state='active' AND active_slot=1",gmdate('Y-m-d H:i:s'),get_current_user_id(),$reason,$old->id));if($changed!==1)throw new \RuntimeException('portal_capability_generation_conflict');$result=$this->mint($lessonId,$scheduleVersionId,$purpose,$expiresAt,$joinTarget,$old->subject_student_id===null?null:(int)$old->subject_student_id,false);$linked=$wpdb->query($wpdb->prepare("UPDATE {$this->table('portal_public_capabilities')} SET superseded_by_capability_id=%d WHERE id=%d AND superseded_by_capability_id IS NULL",$result['capability_id'],$old->id));if($linked!==1)throw new \RuntimeException('portal_capability_persistence_failed');$this->event($lessonId,(int)$old->id,$purpose,(int)$old->generation,'rotated',$reason);$this->command($lessonId,$purpose,'rotate',$reason,(int)$result['capability_id'],'active',$commandKey,$payload);$wpdb->query('COMMIT');return$result;}catch(\Throwable$e){$wpdb->query('ROLLBACK');throw$e;} }
    private function transition(int $id,string $reason,string $state,?string $commandKey=null):void { if(!current_user_can('dzn_manage_portal_capabilities'))throw new \RuntimeException('Unauthorized');PortalRule::operatorReason($reason);$commandKey=$commandKey?:wp_generate_uuid4();global $wpdb;$wpdb->query('START TRANSACTION');try{$lesson=(int)$wpdb->get_var($wpdb->prepare("SELECT lesson_id FROM {$this->table('portal_public_capabilities')} WHERE id=%d",$id));if($lesson<1)throw new \InvalidArgumentException('portal_capability_unknown');$wpdb->get_row($wpdb->prepare("SELECT id FROM {$this->table('portal_lesson_capability_roots')} WHERE lesson_id=%d FOR UPDATE",$lesson));$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->table('portal_public_capabilities')} WHERE id=%d FOR UPDATE",$id));if(!$row)throw new \InvalidArgumentException('portal_capability_unknown');$payload=wp_json_encode(array($id,$reason,$state));if($replay=$this->replayCommand($commandKey,$payload,$lesson,(string)$row->purpose)){$wpdb->query('COMMIT');return;}$wpdb->query($wpdb->prepare("UPDATE {$this->table('portal_public_capabilities')} SET state=%s,active_slot=NULL,revoked_at=%s,revoked_by=%d,revocation_reason_code=%s WHERE id=%d AND state='active'",$state,gmdate('Y-m-d H:i:s'),get_current_user_id(),$reason,$id));$this->event((int)$row->lesson_id,$id,$row->purpose,(int)$row->generation,$state,$reason);$this->command((int)$row->lesson_id,$row->purpose,'revoke',$reason,$id,$state,$commandKey,$payload);$wpdb->query('COMMIT');}catch(\Throwable$e){$wpdb->query('ROLLBACK');throw$e;} }
}
